public static str getDataflowToken(str _authUrl,
                                   str _clientId,
                                   str _clientSecret)
{
    System.Net.HttpWebRequest       request;
    System.Net.HttpWebResponse      response;
    System.Text.ASCIIEncoding       encodingASCII;
    System.Net.WebHeaderCollection  httpHeader;
    QYGD_OAAuthorizationToken       authorizationToken = new QYGD_OAAuthorizationToken();
    GYGD_OAAccessToken              accessToken        = new GYGD_OAAccessToken();
    System.IO.Stream                requestStream, receiveStream;
    System.IO.StreamReader          readStream;
    CLRObject                       clrObj;
    str                             postData;
    System.DateTime                 dateTime = DateTimeUtil::getSystemDateTime();
    System.DateTimeOffset           curDateTime = new System.DateTimeOffset(dateTime);
    TimeOfDay                       time    = curDateTime.ToUnixTimeSeconds();
    //str                             signMD5 = Global::encryptMD5(strFmt("%1%2%3", _clientId, time, _clientSecret));
    ;

    try
    {
        new InteropPermission(InteropKind::ClrInterop).assert();
        httpHeader = new System.Net.WebHeaderCollection();
        clrObj  = System.Net.WebRequest::Create(_authUrl);
        request = clrObj;

        request.set_Method("POST");
        request.set_KeepAlive(true);
        request.set_ContentType("application/json");

        //postData  = strFmt('{"clientid":"%1", "time": "%2", "signature":"%3"}', _clientId, time, signMD5);

        encodingASCII = new System.Text.ASCIIEncoding();
        var data                = encodingASCII.GetBytes(postData);
        request.ContentLength   = data.Length;
        requestStream = request.GetRequestStream();
        requestStream.Write(data, 0, data.Length);
        requestStream.Close();

        response        = request.GetResponse();
        receiveStream   = response.GetResponseStream();
        readStream      = new System.IO.StreamReader(receiveStream, System.Text.Encoding::get_UTF8());

        str result          = readStream.ReadToEnd();
        authorizationToken  = FormJsonSerializer::deserializeObject(classNum(QYGD_OAAuthorizationToken), result);

        if (authorizationToken.paramSuccess())
        {
            accessToken = authorizationToken.parmData();
        }

        response.Close();
        readStream.Close();
    }
    catch (Exception::CLRError)
    {
        System.Exception ex = ClrInterop::getLastException();
        if (ex != null)
        {
            ex = ex.get_InnerException();
            error(ex.Message);
        }
    }

    return accessToken.accessToken;

}

public static DimensionDefault appendDimensions(DimensionDefault    _origDefaultDimension,
                                                container           _conDimensions)
{
    container           origDim         = _origDefaultDimension ? getDimensionAttributeValueSetValue(_origDefaultDimension) : conNull();
    container           dimensionValue;
    DimensionDefault    dimensionSetId;
    int                 attributeCount  = (conLen(origDim) > 0) ? conPeek(origDim, 1) : 0;
    int                 newAttrCount    = attributeCount + (conLen(_conDimensions) / 2);
    Counter             pos;

    //组合新旧维度
    dimensionValue = (conLen(origDim) > 0) ? conPoke(origDim, 1, newAttrCount) : conIns(dimensionValue, 1, newAttrCount);
    for (pos = 1; pos <= conLen(_conDimensions); pos++)
    {
        dimensionValue += [conPeek(_conDimensions, pos)];
    }
    //获取新维度值的RECID
    dimensionSetId = getDimensionAttributeValueSetId(dimensionValue);

    return dimensionSetId;
}

static Name getDimensionValue(RefRecId _defaultDimension, Name _dimensionName)
{
    container dimensioncon;

    dimensioncon = getDimensionAttributeValueSetValue(_defaultDimension);
    if (conFind(dimensioncon, _dimensionName))
    {
        return conPeek(dimensioncon, conFind(dimensioncon, _dimensionName)+1);
    }
    else
    {
        return "";
    }
}

public static DimensionAttribute validateFinancialDimension(str _dimensionName)
{
    #DimensionServiceFaults
    DimensionAttribute  dimensionAttribute;

    dimensionAttribute = DimensionAttribute::findByName(_dimensionName);

    if (!dimensionAttribute)
    {
        AifFault::checkFailedLogFault(strFmt("@SYS342559", _dimensionName), #DimensionAttributeDoesNotExist);
        throw AifFault::faultList("@SYS98197", #ValidationFailed);
    }

    return dimensionAttribute;
}

public static recId getDimensionAttributeValueSetId(container _dimensionValue, dataAreaId _dataAreaId = curext())
{
    recId                               dimensionId;
    DimensionAttributeValueSetStorage   storage;
    DimensionAttribute                  dimensionAttribute;
    DimensionAttributeValue             dimensionAttributeValue;
    int                                 attributeCount, attributeIndex;
    str                                 attributeName, attributeValue;
    int                                 containerElementIndex;

    changecompany(_dataAreaId)
    {
        containerElementIndex = 1;

        storage = new DimensionAttributeValueSetStorage();

        // Get attribute count
        attributeCount = conPeek(_dimensionValue, containerElementIndex);
        containerElementIndex++;

        // Get attributes
        for (attributeIndex = 1; attributeIndex <= attributeCount; attributeIndex++)
        {
            // Get attribute name
            attributeName = conPeek(_dimensionValue, containerElementIndex);
            containerElementIndex++;

            // Validate the Financial Dimenion that was passed in.
            dimensionAttribute = Global::validateFinancialDimension(attributeName);

            // Get attribute value
            attributeValue = conPeek(_dimensionValue, containerElementIndex);
            containerElementIndex++;

            // Validate the Financial Dimenion Value that was passed in.
            dimensionAttributeValue = Global::validateFinancialDimensionValue(dimensionAttribute, attributeValue);

            // Add attribute
            storage.addItem(dimensionAttributeValue);
        }

        dimensionId = storage.save();
    }

    return dimensionId;
}

public static DimensionAttributeValue validateFinancialDimensionValue(DimensionAttribute _dimensionAttribute, str _dimensionValue)
{
    #DimensionServiceFaults
    DimensionAttributeValue dimensionAttributeValue;

    dimensionAttributeValue = DimensionAttributeValue::findByDimensionAttributeAndValueNoError(_dimensionAttribute, _dimensionValue, false, true);

    if (!dimensionAttributeValue)
    {
        AifFault::checkFailedLogFault(strFmt("@SYS342560", _dimensionValue), #DimensionAttributeValueDoesNotExist);
        throw AifFault::faultList("@SYS98197", #ValidationFailed);
    }

    return dimensionAttributeValue;
}

public static container getDimensionAttributeValueSetValue(recId _dimensionId)
{
    container                           value;
    DimensionAttributeValueSetStorage   storage;
    int                                 attributeCount, attributeIndex;
    str                                 attributeName, attributeValue;

    value = conNull();

    // Get storage
    storage = DimensionAttributeValueSetStorage::find(_dimensionId);

    // Add attribute count
    attributeCount = storage.elements();
    value += attributeCount;

    // Add attributes
    for (attributeIndex = 1; attributeIndex <= attributeCount; attributeIndex++)
    {
        // Add attribute name
        attributeName = DimensionAttribute::find(storage.getAttributeByIndex(attributeIndex)).Name;
        value += attributeName;

        // Add attribute value
        attributeValue = DimensionAttributeValue::find(storage.getValueByIndex(attributeIndex)).getValue();
        value += attributeValue;
    }

    return value;
}
